var input = $input.first().json;
return [{ json: {
  requestId: input.requestId, category: input.category, businessName: input.businessName,
  researchStatus: 'not_in_category', demo: true,
  message: "LordGen's live diagnostic currently covers Eatery/Restaurant, Law Firm, Salon & Beauty, and Logistics businesses. This category isn't supported yet.",
  standard: [], research: [], clientRequested: []
} }];

const orig = $('Normalize & Validate').first().json;
const rows = $input.all().map(item => item.json);

const requestId = orig.requestId;
const clientIp = orig.clientIp;

const dupRow = rows.find(r => r.request_id && r.request_id === requestId && r.stage === 'diagnostic');
const isDuplicate = !!dupRow;

const fiveMinAgo = Date.now() - 5 * 60 * 1000;
const recentForIp = rows.filter(r => r.client_ip && r.client_ip === clientIp && r.stage === 'diagnostic' && r.createdAt && new Date(r.createdAt).getTime() >= fiveMinAgo);
const rateLimited = !isDuplicate && recentForIp.length >= 10;

return [{ json: {
  requestId: orig.requestId, category: orig.category, businessName: orig.businessName,
  mode: orig.mode, problem: orig.problem, specialRequest: orig.specialRequest,
  contactEmail: orig.contactEmail, currentTools: orig.currentTools, scale: orig.scale,
  integrationNeeds: orig.integrationNeeds, clientIp: orig.clientIp,
  isDuplicate: isDuplicate,
  cachedStatus: dupRow ? dupRow.status : '',
  cachedResponseJson: dupRow ? dupRow.response_json : '',
  rateLimited: rateLimited
} }];

var input = $input.first().json;
if (input.cachedStatus === 'complete' && input.cachedResponseJson) {
  try {
    return [{ json: JSON.parse(input.cachedResponseJson) }];
  } catch (e) {}
}
return [{ json: {
  requestId: input.requestId, category: input.category, businessName: input.businessName,
  researchStatus: 'processing', demo: true,
  message: 'This request is already being researched. Please wait a moment and check again.',
  standard: [], research: [], clientRequested: []
} }];

var input = $input.first().json;
return [{ json: {
  requestId: input.requestId, category: input.category, businessName: input.businessName,
  researchStatus: 'rate_limited', demo: true,
  message: 'Too many diagnostic requests from this connection in a short time. Please try again in a few minutes.',
  standard: [], research: [], clientRequested: []
} }];

