const ctx = $('Evaluate Request Status').first().json;
const raw = $input.first().json;
const result = raw.output || raw;
return [{ json: {
  requestId: ctx.requestId,
  category: ctx.category,
  businessName: ctx.businessName,
  mode: ctx.mode,
  demo: true,
  researchStatus: result.researchStatus || 'complete',
  confidence: result.confidence || 'medium',
  sources: result.sources || [],
  standard: result.standard || [],
  research: result.research || [],
  clientRequested: result.clientRequested || []
} }];

const input = $input.first().json;
const body = input.body || {};
const headers = input.headers || {};
const VALID_CATEGORIES = ['eatery', 'law_firm', 'salon_beauty', 'logistics'];

const requestId = body.requestId || ('diag-' + Date.now());
const category = String(body.category || '').toLowerCase().trim();
const businessName = String(body.businessName || '').trim();
const mode = body.mode === 'deep' ? 'deep' : 'standard';
const problem = body.problem || '';
const specialRequest = body.specialRequest || '';
const contactEmail = body.contactEmail || '';
const currentTools = body.currentTools || '';
const scale = body.scale || '';
const integrationNeeds = body.integrationNeeds || '';
const clientIp = String(headers['x-forwarded-for'] || '').split(',')[0].trim();

const missingFields = !businessName || !category;
const categoryValid = VALID_CATEGORIES.indexOf(category) !== -1;

return [{ json: {
  requestId: requestId, category: category, businessName: businessName, mode: mode,
  problem: problem, specialRequest: specialRequest, contactEmail: contactEmail,
  currentTools: currentTools, scale: scale, integrationNeeds: integrationNeeds,
  clientIp: clientIp, missingFields: missingFields, categoryValid: categoryValid
} }];

const tavily = $input.first().json;
const results = (tavily.results || []).slice(0, 5).map((r, i) => `[${i+1}] ${r.title || ''}\nURL: ${r.url || ''}\n${r.content || ''}`).join('\n\n');
const answer = tavily.answer || '';
return [{ json: {
  searchContext: (answer ? ('Summary: ' + answer + '\n\n') : '') + (results || 'No search results found.'),
  searchResultCount: (tavily.results || []).length
} }];
